public async Task LoadFile(string path, double startPositionSeconds = 0)
{
    var diagSeq = Interlocked.Increment(ref _diagLoadSeq);
    var diagStart = Nikse.SubtitleEdit.Logic.VideoPlayers.PlayerDiagnostics.Now;
    Interlocked.Increment(ref _diagLoadsInFlight);
    Nikse.SubtitleEdit.Logic.VideoPlayers.PlayerDiagnostics.Log("load", $"#{diagSeq} begin media={Nikse.SubtitleEdit.Logic.VideoPlayers.PlayerDiagnostics.MediaTag(path)} start={Nikse.SubtitleEdit.Logic.VideoPlayers.PlayerDiagnostics.N(startPositionSeconds)} {DiagnosticsState()}");
    try
    {
        await LoadFileCore(path, startPositionSeconds, diagSeq);
    }
    catch (Exception diagException)
    {
        Nikse.SubtitleEdit.Logic.VideoPlayers.PlayerDiagnostics.Log("load", $"#{diagSeq} threw {diagException.GetType().Name}: {Nikse.SubtitleEdit.Logic.VideoPlayers.PlayerDiagnostics.Redact(diagException.Message)}");
        throw;
    }
    finally
    {
        Interlocked.Decrement(ref _diagLoadsInFlight);
        Nikse.SubtitleEdit.Logic.VideoPlayers.PlayerDiagnostics.Log("load", $"#{diagSeq} returned after {Nikse.SubtitleEdit.Logic.VideoPlayers.PlayerDiagnostics.Now - diagStart} ms {DiagnosticsState()}");
    }
}

private async Task LoadFileCore(string path, double startPositionSeconds, int diagSeq)
{
    EnsureNotDisposed();

var diagCoreWait = Nikse.SubtitleEdit.Logic.VideoPlayers.PlayerDiagnostics.Now;
Nikse.SubtitleEdit.Logic.VideoPlayers.PlayerDiagnostics.Log("load", $"#{diagSeq} waiting for core (core={_coreInitialized})");
await WaitForCoreInitializedAsync();
Nikse.SubtitleEdit.Logic.VideoPlayers.PlayerDiagnostics.Log("load", $"#{diagSeq} core wait done after {Nikse.SubtitleEdit.Logic.VideoPlayers.PlayerDiagnostics.Now - diagCoreWait} ms core={_coreInitialized} disposed={_disposed}");

if (!_coreInitialized)
{
    if (_disposed)
    {
        Nikse.SubtitleEdit.Logic.VideoPlayers.PlayerDiagnostics.Log("load", $"#{diagSeq} not sent: player disposed while waiting for core");
        return;
    }

var diagPauseRc = DoMpvCommand("set", "pause", "yes");
if (diagPauseRc >= 0)
{
    SetObservedPause(true);
}

Nikse.SubtitleEdit.Logic.VideoPlayers.PlayerDiagnostics.Log("load", $"#{diagSeq} set pause=yes rc={diagPauseRc}");

