// A blocked native command cannot be cancelled; the watchdog only reports it.
var diagCommandStart = Nikse.SubtitleEdit.Logic.VideoPlayers.PlayerDiagnostics.Now;
var diagCommandDone = 0;
Nikse.SubtitleEdit.Logic.VideoPlayers.PlayerDiagnostics.Log("load", $"#{diagSeq} loadfile sent media={Nikse.SubtitleEdit.Logic.VideoPlayers.PlayerDiagnostics.MediaTag(path)} prefixed={!string.Equals(loadPath, path, StringComparison.Ordinal)}");
using var diagWatchdog = new System.Threading.Timer(_ =>
{
    if (Volatile.Read(ref diagCommandDone) == 0)
    {
        Nikse.SubtitleEdit.Logic.VideoPlayers.PlayerDiagnostics.Log("load", $"#{diagSeq} loadfile STILL BLOCKED after {Nikse.SubtitleEdit.Logic.VideoPlayers.PlayerDiagnostics.Now - diagCommandStart} ms {DiagnosticsState()}");
    }
}, null, 5000, 15000);
var err = await Task.Run(() => DoMpvCommand("loadfile", loadPath));
Volatile.Write(ref diagCommandDone, 1);
Nikse.SubtitleEdit.Logic.VideoPlayers.PlayerDiagnostics.Log("load", $"#{diagSeq} loadfile returned rc={err} ({(err < 0 ? GetErrorString(err) : "ok")}) after {Nikse.SubtitleEdit.Logic.VideoPlayers.PlayerDiagnostics.Now - diagCommandStart} ms disposed={_disposed}");
if (_disposed)
{
    return;
}

