internal async Task Open(string videoFileName, double startPositionSeconds = 0)
{
    var diagGeneration = Nikse.SubtitleEdit.Logic.VideoPlayers.PlayerDiagnostics.NewOpenGeneration();
    System.Threading.Interlocked.Exchange(ref _diagOpenGeneration, diagGeneration);
    Nikse.SubtitleEdit.Logic.VideoPlayers.PlayerDiagnostics.Log("open", $"g={diagGeneration} begin media={Nikse.SubtitleEdit.Logic.VideoPlayers.PlayerDiagnostics.MediaTag(videoFileName)} start={Nikse.SubtitleEdit.Logic.VideoPlayers.PlayerDiagnostics.N(startPositionSeconds)} {DiagnosticsState()}");
    if (IsDisposed)
    {
        Nikse.SubtitleEdit.Logic.VideoPlayers.PlayerDiagnostics.Log("open", $"g={diagGeneration} ignored: control disposed");
        return;
    }

var diagLoadStart = Nikse.SubtitleEdit.Logic.VideoPlayers.PlayerDiagnostics.Now;
System.Threading.Interlocked.Increment(ref _diagOpensInFlight);
try
{
    await _videoPlayerInstance.LoadFile(videoFileName, startPositionSeconds);
}
finally
{
    System.Threading.Interlocked.Decrement(ref _diagOpensInFlight);
}

var diagLatest = System.Threading.Interlocked.Read(ref _diagOpenGeneration);
Nikse.SubtitleEdit.Logic.VideoPlayers.PlayerDiagnostics.Log("open", $"g={diagGeneration} LoadFile awaited {Nikse.SubtitleEdit.Logic.VideoPlayers.PlayerDiagnostics.Now - diagLoadStart} ms" +
    (diagLatest != diagGeneration ? $" SUPERSEDED by g={diagLatest}" : string.Empty) + $" {DiagnosticsState()}");

